fn main(){let args=std::env::args().collect::<Vec<_>>();let mut data=Vec::new();std::io::stdin().read_to_end(&mut data).unwrap();let mut i=Input{data,at:0};let mut o=Output(Vec::new());physics::migration_state_conditioning_run(std::path::Path::new(&args[1]),std::path::Path::new(&args[2]),&mut i,&mut o).unwrap();assert_eq!(i.at,i.data.len());let mut output=std::io::BufWriter::new(std::io::stdout().lock());for w in o.0{output.write_all(&w.to_le_bytes()).unwrap();}}
